main.script:
(function () {
    function hasClass(node, className) {
        return node.className && (" " + node.className + " ").indexOf(" " + className + " ") >= 0;
    }

    function hasAnyClass(node, classNames) {
        for (var i = 0; i < classNames.length; i++) {
            if (hasClass(node, classNames[i])) {
                return true;
            }
        }
        return false;
    }

    function getTextLength(node) {
        return (node.textContent || "").replace(/\s+/g, " ").replace(/ـ/g, "").trim().length;
    }

    function shouldSkipElement(node) {
        if (!node || node.nodeType !== 1) {
            return true;
        }

        if (hasClass(node, "ar-auto-justify") || node.getAttribute("data-no-auto-justify") === "1") {
            return true;
        }

        var tag = node.tagName.toLowerCase();
        if (
            tag === "script" || tag === "style" || tag === "img" || tag === "svg" ||
            tag === "table" || tag === "thead" || tag === "tbody" || tag === "tr" ||
            tag === "h1" || tag === "h2" || tag === "h3" || tag === "h4" || tag === "h5" || tag === "h6"
        ) {
            return true;
        }

        if (hasAnyClass(node, [
            "title",
            "section-title",
            "contract-section-title",
            "audit-responsibility-title",
            "audit-bullet-symbol",
            "signatures-section",
            "sign-table",
            "bank-table",
            "doc-table"
        ])) {
            return true;
        }

        var styleText = (node.getAttribute("style") || "").replace(/\s+/g, "").toLowerCase();
        if (styleText.indexOf("text-align:left") >= 0 || styleText.indexOf("text-align:center") >= 0) {
            return true;
        }

        if (node.closest && node.closest(".signatures-section, .sign-table, .bank-table")) {
            return true;
        }

        /* لا نطبق على النصوص القصيرة جداً إلا لو كانت من كلاس معروف */
        if (
            !hasAnyClass(node, ["contract-paragraph", "contract-paragraph1", "audit-bullet-text", "para", "ar-js-justify"]) &&
            getTextLength(node) < 80
        ) {
            return true;
        }

        return false;
    }

    function wrapTextNode(textNode) {
        var text = textNode.nodeValue;

        if (!text || !text.replace(/\s+/g, "")) {
            return;
        }

        /* إزالة أي كشيدة موجودة فعليًا في النص */
        text = text.replace(/ـ/g, "");

        var parts = text.split(/(\s+)/);
        var frag = document.createDocumentFragment();

        for (var i = 0; i < parts.length; i++) {
            var part = parts[i];

            if (!part) {
                continue;
            }

            if (/^\s+$/.test(part)) {
                frag.appendChild(document.createTextNode(part));
            } else {
                var span = document.createElement("span");
                span.className = "ar-word";
                span.appendChild(document.createTextNode(part));
                frag.appendChild(span);
            }
        }

        textNode.parentNode.replaceChild(frag, textNode);
    }

    function walk(node) {
        if (node.nodeType === 3) {
            wrapTextNode(node);
            return;
        }

        if (node.nodeType !== 1) {
            return;
        }

        var tag = node.tagName.toLowerCase();

        if (
            tag === "script" || tag === "style" || tag === "img" || tag === "svg" ||
            tag === "br" || tag === "table" || tag === "thead" || tag === "tbody" || tag === "tr" ||
            tag === "h1" || tag === "h2" || tag === "h3" || tag === "h4" || tag === "h5" || tag === "h6" ||
            hasClass(node, "ar-word") || hasClass(node, "icon-saudi_riyal")
        ) {
            return;
        }

        var children = [];
        for (var i = 0; i < node.childNodes.length; i++) {
            children.push(node.childNodes[i]);
        }

        for (var j = 0; j < children.length; j++) {
            walk(children[j]);
        }
    }

    function runArabicJustifyFix() {
        var selector = [
            ".contract-paragraph",
            ".contract-paragraph1",
            ".audit-bullet-text",
            ".para",
            ".ar-js-justify",
            ".time-section",
            ".contract-page > div",
            ".contract-body > div"
        ].join(", ");

        var elements = document.querySelectorAll(selector);

        for (var i = 0; i < elements.length; i++) {
            if (shouldSkipElement(elements[i])) {
                continue;
            }

            elements[i].className += " ar-auto-justify";
            walk(elements[i]);
        }
    }

    if (document.readyState === "loading") {
        document.addEventListener("DOMContentLoaded", runArabicJustifyFix);
    } else {
        runArabicJustifyFix();
    }
})();
